		["-- ? Card"] = "-- ? Карта",
		["-- A Card Against Humanity"] = "-- Карта против человечества",
		["-- A Holy Card for 5 pennies."] = "-- «Святая карта» за 5 пенни.",
		["-- A Soul Heart, a pill, a Key, a Bomb or a Nickel."] = "-- Синее сердце, пилюлю, ключ, бомбу или никель.",
		["-- A Soul heart for 5 pennies."] = "-- Синее сердце за 5 пенни.",
		["-- A bomb, which will explode after 1.5 seconds even if Isaac doesn't throw it. This bomb looks like a Butt Bomb, but will not have its unique effect. It will, however, use Isaac's bomb synergies."] = "-- Бомба — взорвётся через 1.5 секунды, даже если Исаак её не бросит. Выглядит как «Бомба из задницы», но её особого эффекта нет. Зато учитывает сочетания бомб Исаака.",
		["-- A burning poop that leaves behind a fire that damages enemies and blocks enemy shots. The fire lasts 5 seconds and can block five shots and/or deal three ticks of contact damage before disappearing (the first hit will deal 16.5 damage, the second and third will deal 11)."] = "-- Горящая какашка: оставляет огонь, ранящий врагов и загораживающий их выстрелы. Огонь держится 5 секунд и выдерживает пять выстрелов и/или три такта урона касанием (первый удар — 16.5 урона, второй и третий — по 11).",
		["-- A corny poop that spawns a blue fly every two seconds. Each corny poop can have up to 3 blue flies out at a time."] = "-- Кукурузная какашка: каждые две секунды создаёт синюю муху. У каждой — до 3 синих мух одновременно.",
		["-- A gray poop that is very resistant to damage and deals extra damage when thrown."] = "-- Серая какашка: очень прочная и наносит больше урона при броске.",
		["-- A green poop that emits a toxic cloud that deals 3.5 damage per tick to nearby enemies (10.5 damage per second). If an explosion or fire hits the cloud, it also explodes, dealing 15 damage to anything caught in the blast. When the poop is destroyed, it spawns a larger toxic cloud that can't explode and goes away after 5 seconds."] = "-- Зелёная какашка: испускает ядовитое облако — 3.5 урона за такт ближним врагам (10.5 в секунду). Если в облако попадёт взрыв или огонь, оно тоже взрывается, нанося 15 урона всему в зоне взрыва. Разрушенная какашка выпускает облако побольше, которое не взрывается и рассеивается через 5 секунд.",
		["-- A key for 5 pennies."] = "-- Ключ за 5 пенни.",
		["-- A normal poop."] = "-- Обычная какашка.",
		["-- A normal wisp is white and blue, has 2 health and spectral tears which deal 1.6-2.4 damage, and is summoned in the middle ring."] = "-- Обычный огонёк бело-синий, у него 2 здоровья и спектральные слёзы на 1.6-2.4 урона; появляется в среднем кольце.",
		["-- A white poop, which acts the same as the one created by Hallowed Ground. Isaac also gains the poop's effects while holding it."] = "-- Белая какашка — такая же, как от «Священной земли». Пока Исаак её держит, её эффекты действуют и на него.",
		["-- A wisp's health can be determined by its size, shrinking as its health decreases."] = "-- Здоровье огонька видно по размеру: он уменьшается вместе со здоровьем.",
		["-- Ace of Clubs"] = "-- Туз Треф",
		["-- Ace of Diamonds"] = "-- Туз Бубен",
		["-- Ace of Hearts"] = "-- Туз Червей",
		["-- Ace of Spades"] = "-- Туз пик",
		["-- Addicted!"] = "-- Зависимый!",
		["-- After colliding with an obstacle or getting sufficiently shot by Isaac, Frozen enemies will Explode into a ring of 10 ice tears that can Slow and Freeze."] = "-- Ударившись о препятствие или получив достаточно выстрелов Исаака, замёрзшие враги взрываются кольцом из 10 ледяных слёз, которые замедляют и замораживают.",
		["-- Amnesia"] = "-- Амнезия",
		["-- An Eternal heart for 5 pennies."] = "-- Вечное сердце за 5 пенни.",
		["-- An item from the Angel Room Item Pool for 15 pennies. High quality items cost 30 pennies."] = "-- Предмет из пула комнаты ангела за 15 пенни. Предметы высокого качества — 30 пенни.",
		["-- Ancient Recall"] = "-- Древний Зов",
		["-- BFFS! will continue to work on Isaac even after absorption, doubling damage dealt."] = "-- «Лучшие друзья навек!» продолжают действовать на Исаака и после поглощения, удваивая урон.",
		["-- Bad Gas"] = "-- Вонючий газ",
		["-- Bad Trip"] = "-- Плохой приход",
		["-- Bag of Crafting"] = "-- Созидательный мешок",
		["-- Balls of Steel"] = "-- Стальные яйца",
		["-- Black Hearts will drop as soon as the enemy is killed. (In other words, the heart will drop at the beginning of the death animation rather than at the end of the death animation.)"] = "-- Чёрное сердце выпадает сразу при убийстве врага. (То есть в начале анимации смерти, а не в конце.)",
		["-- Black Rune"] = "-- Чёрная руна",
		["-- Blank Rune"] = "-- Пустая руна",
		["-- Bombs are Key"] = "-- Бомбы = Ключи",
		["-- Both effects stack up to six times, for a total of +1.02 speed and +3 tears."] = "-- Оба эффекта складываются до шести раз — всего +1.02 к скорости и +3 к скорострельности.",
		["-- Bullets walked through will still count for the final blast damage calculation, even though they can't really be damaged."] = "-- Пройденные пули тоже учитываются в итоговом уроне взрыва, хотя ранить их на самом деле нельзя.",
		["-- Chaos Card"] = "-- Карта Хаоса",
		["-- Crafting an activated item while already holding one will turn the old one into pickups like collecting it would."] = "-- Если создать активный предмет, когда активный уже есть, старый превратится в подборы, как при подборе.",
		["-- Credit Card"] = "-- Кредитная карта",
		["-- Curse of the Blind hides the crafting preview."] = "-- «Проклятие Слепоты» скрывает предпросмотр создания.",
		["-- Damage -1, 0 or +1."] = "-- Урон -1, 0 или +1.",
		["-- Damage applied on an enemy also depends on distance between the enemy and Isaac"] = "-- Урон по врагу зависит и от расстояния между врагом и Исааком",
		["-- Despite the blasts decreasing in size after passing through obstacles, this is aesthetic as the blast will only damage enemies adjacent to the obstacle."] = "-- Хотя вспышки уменьшаются, пролетая сквозь препятствия, это только внешне: вспышка ранит лишь врагов рядом с препятствием.",
		["-- Devil/Angel room items can cost up to 50 cents, and Secret Room items can cost up to 99 cents."] = "-- Предметы дьявола/ангела стоят до 50 центов, предметы секретной комнаты — до 99 центов.",
		["-- Draining health does not count as taking damage, so creating familiars will not trigger damage-activated effects."] = "-- Отнятие здоровья уроном не считается, так что создание спутников не вызывает эффекты от урона.",
		["-- During the delay when transitioning between rooms, picking up an item, or using an active item, it's possible to change the firing direction without resetting the bonus."] = "-- Во время задержки при переходе между комнатами, подборе предмета или использовании активного предмета можно сменить направление стрельбы, не сбрасывая прибавку.",
		["-- Enemies also spawn in front of Secret Room and Super Secret Room"] = "-- Враги появляются и перед секретной и суперсекретной комнатами",
		["-- Enemy shots that get pulled in will now also damage enemies other than the ones that fired them."] = "-- Втянутые выстрелы врагов теперь ранят и других врагов, а не только стрелявших.",
		["-- Era Walk"] = "-- Прогулка по Эпохе",
		["-- Experimental Pill"] = "-- Экспериментальная пилюля",
		["-- Explosive Diarrhea"] = "-- Взрывная диарея",
		["-- Familiars that have a random chance to drop items have a higher chance."] = "-- У тех, кто роняет предметы с шансом, шанс выше.",
		["-- Familiars that pick up consumables require less, except Dark Bum which is unaffected."] = "-- Тем, кто подбирает расходники, нужно меньше, кроме «Тёмного бездельника» — на него не действует.",
		["-- Familiars that require clearing a certain number of rooms will require one less room."] = "-- Тем, кому нужно зачистить сколько-то комнат, нужно на одну меньше.",
		["-- Feels like I'm walking on sunshine!"] = "-- Как будто я гуляю под солнцем!",
		["-- Fire Poops create Fire Dips that burn enemies they hit and leave behind a fire when they die."] = "-- Из огненных какашек — огненные Капли: поджигают задетых врагов и при смерти оставляют огонь.",
		["-- Flip"] = "-- Переворот",
		["-- Friends Till The End!"] = "-- Друзья до конца",
		["-- Full Health"] = "-- Полное здоровье",
		["-- Further uses of Sulfur will continue increasing Isaac's damage, but will not increase the size of the laser."] = "-- Дальнейшие использования «Сульфура» продолжают повышать урон, но лазер больше не растёт.",
		["-- Get out of Jail Free Card"] = "-- Карта выхода из тюрьмы",
		["-- Green Poops create Toxic Dips that release toxic gas as they move and a larger cloud of toxic gas when they die."] = "-- Из зелёных какашек — ядовитые Капли: на ходу выпускают ядовитый газ, а при смерти — большое облако газа.",
		["-- Gulp!"] = "-- Глотай!",
		["-- Has no effect on Creep generated by familiars."] = "-- На лужи от спутников не действует.",
		["-- Hematemesis"] = "-- Кровавая рвота",
		["-- Hold"] = "-- Удержание",
		["-- Holy Card"] = "-- Святая карта",
		["-- Horf!"] = "-- Хорф!",
		["-- However, Devil Deals can still be taken for free."] = "-- При этом сделки с дьяволом по-прежнему бесплатны.",
		["-- However, getting an item from a Red Chest will keep the icon."] = "-- Но если из красного сундука выпал предмет, значок остаётся.",
		["-- Huge Growth"] = "-- Огромный Рост",
		["-- I - The Magician"] = "-- I - Маг",
		["-- I - The Magician?"] = "-- I - Маг?",
		["-- I Found Pills"] = "-- Я нашел пилюли",
		["-- I can see forever!"] = "-- Я могу видеть вечно!",
		["-- I'm Drowsy..."] = "-- Я сонный...",
		["-- I'm Excited!!!"] = "-- Я взволнован!!!",
		["-- II - The High Priestess"] = "-- II - Верховная Жрица",
		["-- II - The High Priestess?"] = "-- II - Верховная Жрица?",
		["-- III - The Empress"] = "-- III - Императрица",
		["-- III - The Empress?"] = "-- III - Императрица?",
		["-- IV - The Emperor"] = "-- IV - Император",
		["-- IV - The Emperor?"] = "-- IV - Император?",
		["-- IX - The Hermit"] = "-- IX - Отшельник",
		["-- IX - The Hermit?"] = "-- IX - Отшельник?",
		["-- If Blood Puppy charges into a live bomb, it will get caught on its mouth, preventing it from moving until it explodes."] = "-- Если «Кровавый щеночек» бросится на горящую бомбу, она застрянет у него в пасти, и он не сдвинется до взрыва.",
		["-- If Cracked Dice selects a die that doesn't affect anything in the room, nothing happens."] = "-- Если «Треснувший кубик» выбрал кубик, которому в комнате нечего менять, ничего не происходит.",
		["-- If Isaac is shielded or invulnerable, his familiars are also immune to damage."] = "-- Если Исаак под щитом или неуязвим, его спутники тоже не получают урона.",
		["-- If [-REP] tears or speed are at their maximum and are chosen, there will be no visible increase."] = "-- Если выпала [-REP] скорострельность или скорость, уже стоящая на пределе, видимой прибавки не будет.",
		["-- If a White Poop's aura is in contact with it, the creep triples Isaac's fire rate and damage in addition to its normal effects while standing on it."] = "-- Если лужи касается аура белой какашки, стоя в луже, Исаак вдобавок к обычным эффектам получает втрое больше скорострельности и урона.",
		["-- If a black poop is in contact with it, the creep also slows enemies and gives Isaac slowing tears while he's standing on it."] = "-- Если лужи касается чёрная какашка, лужа ещё и замедляет врагов, а Исаак, стоя в ней, стреляет замедляющими слезами.",
		["-- If a burning poop is in contact with it, the creep burns enemies and gives Isaac Fire Mind while he's standing on it."] = "-- Если лужи касается горящая какашка, лужа поджигает врагов, а Исаак, стоя в ней, получает «Огненный разум».",
		["-- If a chest in the area contains an item, picking it up will cause Isaac to leave the area."] = "-- Если в сундуке там окажется предмет, взяв его, Исаак покинет это место.",
		["-- If a toxic cloud is in contact with it, the creep poisons enemies and gives Isaac poison tears while he's standing on it."] = "-- Если лужи касается ядовитое облако, лужа отравляет врагов, а Исаак, стоя в ней, стреляет ядовитыми слезами.",
		["-- If an enemy is standing in the center of all the light beams, they will take a total of 152.5 damage."] = "-- Враг в центре всех лучей получит всего 152.5 урона.",
		["-- If playing as The Forgotten, the x2 tear delay modifier isn't applied, as he already has it."] = "-- За Забытого множитель задержки x2 не применяется — он у него уже есть.",
		["-- If the item has no pool (gained as a starting item, fixed drops such as a Blood Bag from a Blood Donation Machine or The Virus from Lust, or gained via the debug console), the Treasure Room pool is used."] = "-- Если у предмета нет пула (стартовый, постоянная награда вроде «Пакета с кровью» из автомата сдачи крови или «Вируса» от Похоти, или выдан через консоль), используется пул сокровищницы.",
		["-- In addition to normal exit door ( when Isaac will use it, he will be teleported back to normal Hush fight ), there is exit for Sheol and Cathedral."] = "-- Кроме обычной двери-выхода (она возвращает Исаака к обычному бою с Молчанием), есть выходы в Преисподнюю и Собор.",
		["-- Infested!"] = "-- Заражение!",
		["-- Infested?"] = "-- Заражение?",
		["-- Isaac will not lose coins from this effect occuring."] = "-- Исаак не теряет монеты от этого эффекта.",
		["-- Isaac's bomb explosions will also damage the familiars."] = "-- Взрывы бомб Исаака тоже ранят этих спутников.",
		["-- Isaac's contact damage increases when absorbing multiple Shade familiars."] = "-- Урон касанием Исаака растёт, если он поглотил несколько Теней.",
		["-- Joker"] = "-- Джокер",
		["-- Killing this boss will count as Hush kill."] = "-- Убийство этого босса засчитывается как убийство Молчания.",
		["-- Lemon Party"] = "-- Лимонадная вечеринка",
		["-- Luck -1, 0 or +1."] = "-- Удача -1, 0 или +1.",
		["-- Minisaacs are immune to spikes and lasers."] = "-- Мини-Исааки не получают урона от шипов и лазеров.",
		["-- One makes you larger"] = "-- Одна сделает тебя крупнее",
		["-- One makes you small"] = "-- Одна сделает тебя меньше",
		["-- Only affects familiars that deal a set amount of damage. Has no effect on most familiars that scale with Isaac's damage."] = "-- Только у спутников с постоянным уроном. На большинство спутников, чей урон зависит от урона Исаака, не действует.",
		["-- Only the ability to pierce enemies on overkill damage is applied, there is no associated damage bonus with the tear."] = "-- Действует только пронзание врагов при избыточном уроне, без прибавки урона слезе.",
		["-- Open chests."] = "-- Открывать сундуки.",
		["-- Opening Red Chests that have been spawned after room generation, e.g. as a room clear reward or enemy drop, won't remove the icon."] = "-- Красные сундуки, появившиеся после создания комнаты (награда за зачистку или выпавшие из врага), значок не убирают.",
		["-- Paralysis"] = "-- Паралич",
		["-- Percs!"] = "-- Обезболивающее",
		["-- Pheremones"] = "-- Феромоны",
		["-- Pick up a Little Battery, collectibles, pills, trinkets, or cards or runes."] = "-- Подбирать маленькие батарейки, предметы, пилюли, брелоки, карты или руны.",
		["-- Pick up the trophy or enter the chest that spawns after defeating Isaac or ???."] = "-- Подобрать трофей или войти в сундук после победы над Исааком или ???.",
		["-- Poisoned enemies do not need to die while the poison is still active to spread the effect."] = "-- Чтобы передать эффект, отравленным врагам не обязательно умереть, пока действует яд.",
		["-- Pooters will not fire at Isaac and Moters will not split into Attack Flies."] = "-- Морилки не стреляют в Исаака, а Парные Мухи не распадаются на Атакующих Мух.",
		["-- Power Pill!"] = "-- Мощная пилюля!",
