		["-- Puberty"] = "-- Зрелость",
		["-- Queen of Hearts"] = "-- Дама Червей",
		["-- R U A Wizard?"] = "-- Ты волшебник?",
		["-- Range -0.5, 0 or +0.5."] = "-- Дальность -0.5, 0 или +0.5.",
		["-- Re-Lax"] = "-- Расслабься",
