		["-- XII - The Hanged Man"] = "-- XII - Повешенный",
		["-- XII - The Hanged Man?"] = "-- XII - Повешенный?",
		["-- XIII - Death"] = "-- XIII - Смерть",
		["-- XIII - Death?"] = "-- XIII - Смерть?",
		["-- XIV - Temperance"] = "-- XIV - Умеренность",
		["-- XIV - Temperance?"] = "-- XIV - Умеренность?",
		["-- XIX - The Sun"] = "-- XIX - Солнце",
