		["-- XV - The Devil"] = "-- XV - Дьявол",
		["-- XV - The Devil?"] = "-- XV - Дьявол?",
		["-- XVI - The Tower"] = "-- XVI - Башня",
		["-- XVI - The Tower?"] = "-- XVI - Башня?",
		["-- XVII - The Stars"] = "-- XVII - Звезды",
		["-- XVII - The Stars?"] = "-- XVII - Звезды?",
		["-- XVIII - The Moon"] = "-- XVIII - Луна",
		["-- XVIII - The Moon?"] = "-- XVIII - Луна?",
		["-- XX - Judgement"] = "-- XX - Суд",
