		["Code by dpower12"] = "Код - dpower12",
		["Code by dpower12, Itemsprite by Reixen, Tear sprite by Reixen"] = "Код - dpower12, спрайт предмета - Reixen, спрайт слезы - Reixen",
		["Code by dpower12, Sprite and costume by Reixen"] = "Код - dpower12, спрайт и костюм - Reixen",
		["Code improved by dpower12"] = "Код улучшил dpower12",
